package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class DurableWorkTest {
    WorkTestSupport w;@Before public void before()throws Exception{w=new WorkTestSupport();}@After public void after(){w.close();}
    @Test public void all1205BooksRemainInTheJournalAndImportWithoutAnActivity()throws Exception{String id=w.importJob(1205);assertEquals(1205,w.items(id,null));w.run(id);assertEquals(1205,w.materials());assertEquals(1205,w.items(id,"done"));try(TaskStore db=new TaskStore(w.app)){ImportReport.save(w.app,db,id);assertEquals("complete",db.job(id).s("state"));}assertTrue(w.app.getSharedPreferences("studies",0).getString("import_summary","").contains("1205 importados"));}
    @Test public void interruptionRetainsCompletedItemsAndResumesOnlyTheRemainder()throws Exception{String id=w.importJob(8);TaskService.Control first=w.control(id);try(TaskStore db=new TaskStore(w.app);StudyStore books=new StudyStore(w.app)){List<StudyStore.Row> items=db.items(id,null,0,8);for(int i=0;i<3;i++)ImportWork.process(w.service,books,db,db.job(id),items.get(i),0,true,first);}assertEquals(3,w.materials());try(TaskStore db=new TaskStore(w.app)){db.item(id,3,StudyStore.values("state","running"));db.recover();assertEquals("queued",db.job(id).s("state"));}w.run(id);assertEquals(8,w.materials());assertEquals(8,w.items(id,"done"));assertEquals(8,StudyFileProvider.directory(w.app).listFiles((d,n)->!n.endsWith(".part")).length);}
    @Test public void aBookLargerThan128MiBStreamsToDiskWithoutTheOldLimit()throws Exception{File file=new File(w.app.getCacheDir(),"large-fixture.pdf");try(RandomAccessFile out=new RandomAccessFile(file,"rw")){out.write("Not a real PDF; metadata must fail softly.\n".getBytes("UTF-8"));out.setLength(129L*1048576+17);}Uri source=w.source("large","Livro grande.pdf",file);String id=w.job("import",new JSONObject().put("scan_complete",true).put("books",true));try(TaskStore db=new TaskStore(w.app)){db.add(id,0,source.toString(),"Livro grande.pdf",file.length(),1);}w.run(id);assertEquals(1,w.items(id,"done"));StudyStore.Row book;try(StudyStore db=new StudyStore(w.app)){book=db.rows("materials",null,null,null,1).get(0);}assertEquals(file.length(),new File(book.s("path")).length());assertEquals(StudyFiles.hash(file),book.s("hash"));}
    @Test public void repeatingTheSameSourcesVerifiesBytesWithoutCreatingMoreCopies()throws Exception{String first=w.importJob(4);w.run(first);int before=StudyFileProvider.directory(w.app).listFiles().length;String next=w.importJob(4);w.run(next);assertEquals(4,w.items(next,"duplicate"));assertEquals(4,w.materials());assertEquals(before,StudyFileProvider.directory(w.app).listFiles().length);try(TaskStore db=new TaskStore(w.app)){for(StudyStore.Row item:db.items(next,null,0,10))assertEquals("",item.s("target"));}}
    @Test public void changedSourceWithTheSameNameProducesANewVersion()throws Exception{String first=w.importJob(1);w.run(first);Files.write(WorkTestSupport.sourceFiles.get("book-0").toPath(),"Conteúdo novo do mesmo nome.\n".getBytes("UTF-8"));String next=w.job("import",new JSONObject().put("scan_complete",true).put("books",true));try(TaskStore db=new TaskStore(w.app)){db.add(next,0,"content://seeky.work.input/book-0","Livro 0.txt",0,0);}w.run(next);assertEquals(2,w.materials());assertEquals(1,w.items(next,"done"));}
    @Test public void tamperedStoredCopyIsNotSilentlyAcceptedAsADuplicate()throws Exception{String first=w.importJob(1);w.run(first);StudyStore.Row book;try(StudyStore db=new StudyStore(w.app)){book=db.rows("materials",null,null,null,1).get(0);}Files.write(new File(book.s("path")).toPath(),"changed stored bytes".getBytes("UTF-8"));String next=w.importJob(1);try{w.run(next);fail();}catch(IOException expected){}assertEquals(1,w.items(next,"failed"));assertEquals(1,w.materials());}
    @Test public void sourceAndFailedRowsSurviveAClosedStoreAndRestart()throws Exception{String id=w.importJob(3);try(TaskStore db=new TaskStore(w.app)){db.item(id,0,StudyStore.values("state","done"));db.item(id,1,StudyStore.values("state","failed"));db.item(id,2,StudyStore.values("state","sent"));db.state(id,"running","Interrupted");}try(TaskStore restarted=new TaskStore(w.app)){restarted.recover();assertEquals("queued",restarted.job(id).s("state"));assertEquals(1,restarted.count(id,"done"));assertEquals(1,restarted.count(id,"uncertain"));restarted.retryFailed(id);assertEquals(1,restarted.count(id,"pending"));assertEquals(1,restarted.count(id,"done"));assertEquals(1,restarted.count(id,"uncertain"));}}
    @Test public void foregroundDriverRunsQueuedWorkAndKeepsAPersistentCompletionRecord()throws Exception{String id=w.importJob(6);try(TaskStore db=new TaskStore(w.app)){db.state(id,"queued","");}w.service.onStartCommand(null,0,1);w.service.worker.submit(()->{}).get(30,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();try(TaskStore db=new TaskStore(w.app)){assertEquals("complete",db.job(id).s("state"));}assertEquals(6,w.materials());assertTrue(w.app.getSharedPreferences("operation_metrics",0).contains("work_last_ms"));}
    @Test public void requestInFlightIsPausedRatherThanAutomaticallyRepeatedAfterRestart()throws Exception{String id=w.job("summary",new JSONObject());try(TaskStore db=new TaskStore(w.app)){db.add(id,0,"content://source","Trecho",1,0);db.item(id,0,StudyStore.values("state","sent"));db.state(id,"running","");db.recover();assertEquals("paused",db.job(id).s("state"));assertEquals(1,db.count(id,"uncertain"));db.retryFailed(id);assertEquals(0,db.count(id,"pending"));}}
}
